parameters.jsCode:
const entrada =
  $('Normalizar y validar entrada').first().json;

const sesion = $json ?? {};

const token = String(
  entrada.session_token ?? ''
).trim();

const usuarioSolicitado = String(
  entrada.usuario_id ?? ''
).trim();

const usuarioSesion = String(
  sesion.usuario_id ?? ''
).trim();

const estadoSesion = String(
  sesion.estado ?? ''
).trim().toUpperCase();

const expiraEn = sesion.expira_en
  ? new Date(sesion.expira_en)
  : null;

let session_valida = true;
let auth_error = null;
let auth_status_http = 401;

// Token obligatorio
if (!token) {
  session_valida = false;
  auth_error = 'El token de sesión es obligatorio';
}

// El token debe existir en EP02
else if (!sesion.session_id) {
  session_valida = false;
  auth_error = 'La sesión no existe o ya no es válida';
}

// La sesión debe estar ACTIVA
else if (estadoSesion !== 'ACTIVA') {
  session_valida = false;
  auth_error = 'La sesión no está activa';
}

// La sesión no puede estar expirada
else if (
  !expiraEn ||
  Number.isNaN(expiraEn.getTime()) ||
  expiraEn.getTime() <= Date.now()
) {
  session_valida = false;
  auth_error = 'La sesión ha expirado';
}

// La sesión debe pertenecer al usuario solicitado
else if (
  !usuarioSolicitado ||
  usuarioSesion !== usuarioSolicitado
) {
  session_valida = false;
  auth_error =
    'No tienes autorización para acceder a este usuario';
  auth_status_http = 403;
}

return [
  {
    json: {
      ...entrada,

      session_valida,

      session_id:
        sesion.session_id ?? null,

      session_usuario_id:
        usuarioSesion || null,

      session_estado:
        estadoSesion || null,

      session_expira_en:
        sesion.expira_en ?? null,

      auth_error,

      auth_status_http:
        session_valida ? 200 : auth_status_http,
    },
  },
];

const auth =
  $('Evaluar sesión WF01').first().json;

const usuario = $json ?? {};

const estadoUsuario = String(
  usuario.estado ?? ''
).trim().toUpperCase();

let usuario_activo = true;

let auth_error =
  auth.auth_error ?? null;

let auth_status_http =
  auth.auth_status_http ?? 200;

// El usuario asociado a la sesión debe existir
if (!usuario.usuario_id) {
  usuario_activo = false;
  auth_error =
    'La cuenta asociada a la sesión no existe';
  auth_status_http = 403;
}

// El usuario asociado debe seguir ACTIVO
else if (estadoUsuario !== 'ACTIVO') {
  usuario_activo = false;
  auth_error =
    'La cuenta asociada a la sesión está inactiva';
  auth_status_http = 403;
}

return [
  {
    json: {
      ...auth,
      usuario_activo,
      usuario_estado:
        estadoUsuario || null,
      auth_error,
      auth_status_http,
    },
  },
];
